mapper.select:
SELECT uph.id, uph.user_id, u.username, uph.change_ip, uph.create_time, uph.update_time, uph.create_user, uph.update_user FROM log_user_password_history uph LEFT JOIN sys_user u ON uph.user_id = u.id AND u.is_deleted = 0
AND uph.user_id = #{query.userId}
AND uph.create_time >= #{query.changeTimeStart}
AND uph.create_time <= #{query.changeTimeEnd}
AND uph.change_ip LIKE CONCAT( #{query.changeIp}, '%' )
ORDER BY uph.create_time DESC
